373:     return best;
374:   }, undefined);
375:   if (!gap) return undefined;
376:   const minutes = Math.round(gap.durationUs / 60_000_000);
377:   const seconds = Math.max(1, Math.round(gap.durationUs / 1_000_000));
378:   const waited =
379:     minutes >= 1
380:       ? `${minutes} ${minutes === 1 ? 'minute' : 'minutes'}`
381:       : `${seconds} ${seconds === 1 ? 'second' : 'seconds'}`;
382:   return `Between games ${gap.afterIndex + 1} and ${gap.beforeIndex + 1} you waited ${waited}.`;
