454: function nearestMoveTo(moves: readonly TimelineMove[], tUs: number): TimelineMove | null {
455:   let best: TimelineMove | null = null;
456:   let bestDist = Infinity;
457:   for (const move of moves) {
458:     if (move.tUs === null) continue;
459:     const dist = Math.abs(move.tUs - tUs);
460:     if (dist <= 2_000_000 && dist < bestDist) {
461:       best = move;
462:       bestDist = dist;
463:     }
464:   }
465:   return best;
466: }
